def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from typing import List, Tuple
    import collections

    # Create a grid of size N x N with all values initialized to 0
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x - 1][y - 1] = value

    # Directions for moving in the grid (right and down)
    directions = [(0, 1), (1, 0)]

    # Initialize a DP table with -1 (invalid values)
    dp = collections.defaultdict(lambda: [-1] * N)
    dp[0][0] = grid[0][0]

    for i in range(N):
        for j in range(N):
            if dp[i][j] == -1:
                continue
            for dx, dy in directions:
                ni, nj = i + dx, j + dy
                if 0 <= ni < N and 0 <= nj < N:
                    dp[ni][nj] = max(dp[ni][nj], dp[i][j] + grid[ni][nj])

    # Find the maximum value in the last row and column
    max_value = 0
    for i in range(N):
        max_value = max(max_value, dp[i][N-1], dp[N-1][i])

    return max_value
