def max_product(num_str: str, N: int, K: int) -> int:
    if N - K - 1 <= 0 or not num_str.isdigit():
        return int(num_str)

    max_parts = K + 1
    max_product = 1
    substring = num_str

    for _ in range(max_parts):
        max_sub = 0
        for i in range(1, len(substring)):
            product = int(substring[:i]) * int(substring[i:])
            if product > max_sub:
                max_sub = product
        max_product *= max_sub
        if i != len(substring) - 1:
            substring = substr(max_sub)

    return max_product

def substr(num):
