def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit():
        raise ValueError("num_str must be a string representing a number")
    if N != len(num_str):
        raise ValueError("N must be equal to the length of num_str")
    if K < 0 or K > len(num_str) - 1:
        raise ValueError("K must be a non-negative integer less than or equal to len(num_str) - 1")

    max_val = 0
    for i in range(1, K + 1):
        left = int(num_str[:i])
        right = int(num_str[i:])
        max_val = max(max_val, left * right)

    return max_val

