    for i in range(9):
        if not isbn[i].isdigit():
            raise ValueError("Invalid character in ISBN")
        weighted_sum += (10 - i) * int(isbn[i])

    calculated_checksum = weighted_sum % 11
    if calculated_checksum == 0:
        expected_checksum = '0'
    elif calculated_checksum == 1:
        expected_checksum = 'X' if isbn[9] == 'X' or isbn[9] == 'x' else '10' % 11
    else:
        expected_checksum = str(11 - calculated_checksum)

    if isbn[9] == expected_checksum or isbn[9].lower() == expected_checksum:
        return "Right"
    else:
        return isbn[:9] + expected_checksum

