def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char.isdigit():
                total += int(char) * (10 - i)
            elif char == 'X':
                total += 10 * (10 - i)
            else:
                return -1
        return total % 11 == 0

    def get_corrected_isbn(isbn: str) -> str:
        last_char = isbn[-1]
        if last_char.isdigit():
            temp_isbn = isbn[:-1] + 'X'
        else:
            temp_isbn = isbn[:-1] + str(10 - (calculate_checksum(isbn[:-1]) % 11))
        return temp_isbn if calculate_checksum(temp_isbn) else isbn

    if not isinstance(isbn, str) or len(isbn) != 13 or '-' not in isbn:
        raise ValueError("Invalid ISBN format")

    parts = isbn.split('-')
    if len(parts) != 4 or not all(part.isdigit() for part in parts[:3]) or not (parts[3].isdigit() or parts[3] == 'X'):
        raise ValueError("Invalid ISBN format")

    if calculate_checksum(isbn):
        return "Right"
    else:
        return get_corrected_isbn(isbn)
