def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input values")
    if n == 1 and m == 0:
        return 1
    dp = [[0] * (m + 1) for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1
    for passes in range(1, m + 1):
        dp[0][passes] = dp[n-1][passes-1]
        dp[n-1][passes] = dp[0][passes-1]
        for i in range(1, n-1):
            dp[i][passes] = dp[i-1][passes-1] + dp[i+1][passes-1]
    return dp[0][m]

