def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("n must be a positive integer and m must be a non-negative integer")

    if n == 1:
        return 1

    dp = [[0] * (m + 1) for _ in range(n)]
    MOD = 10**9 + 7

    for i in range(n):
        dp[i][0] = 1

    for k in range(1, m + 1):
        for i in range(n):
            dp[i][k] = (dp[(i - 1) % n][k - 1] + dp[(i + 1) % n][k - 1]) % MOD

    return dp[0][m]
