        dp[i][0] = 1
        dp[i][i] = 1

    for j in range(1, m + 1):
        dp[0][j] = dp[n - 1][j - 1]

    for i in range(1, n):
        for j in range(1, m + 1):
            dp[i][j] = (dp[i - 1][j - 1] + dp[(i + 1) % n][j - 1]) % 1000000007

    return dp[0][m]
