def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or n % k < k - x:
        return 0
    memo = {}

    def partition(remaining, parts_left, min_value):
        if parts_left == 1:
            return 1
        if (remaining, parts_left, min_value) in memo:
            return memo[(remaining, parts_left, min_value)]
        count = 0
        for i in range(min_value, remaining // parts_left + 1):
            count += partition(remaining - i, parts_left - 1, i)
        memo[(remaining, parts_left, min_value)] = count
        return count

    return partition(n, k, x)
