    if k * x > n:
        return 0
    if k == 1:
        return 1
    dp = [[0 for _ in range(n + 1)] for _ in range(k + 1)]
    for i in range(n + 1):
        dp[1][i] = 1 if i >= x else 0
    for i in range(2, k + 1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i][j - 1] + dp[i - 1][j - i * x] if j >= i * x else dp[i][j - 1]
    return dp[k][n]
