        current_number = queue.popleft()
        unique_numbers.add(current_number)

        for i in range(len(str(current_number))):
            digit = int(str(current_number)[i])
            if digit in rules_dict:
                transformed_number = current_number - (digit * 10**i) + (rules_dict[digit] * 10**i)
