def generate_numbers(n, rules) -> int:
    from collections import deque

    def replace_digit(number, old_digit, new_digit):
        return int(str(number).replace(str(old_digit), str(new_digit)))

    queue = deque([n])
    visited = set()

    while queue:
        current = queue.popleft()
        if current not in visited:
            visited.add(current)
            for old_digit, new_digit in rules:
                new_number = replace_digit(current, old_digit, new_digit)
                if new_number != current and new_number not in visited:
                    queue.append(new_number)

    return len(visited)

