def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if M == 0 or T == 0:
        return 0

    dp = [0] * (T + 1)

    for weight, value in herbs:
        if weight <= T:
            for t in range(T, weight - 1, -1):
                dp[t] = max(dp[t], dp[t - weight] + value)

    return dp[T]
