import functools

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    @functools.lru_cache(None)
    def dp(t, m):
        if m == 0 or t == 0:
            return 0
        if herbs[m-1][0] > t:
            return dp(t, m-1)
        else:
            return max(dp(t, m-1), dp(t-herbs[m-1][0], m-1) + herbs[m-1][1])

    return dp(T, M)
