from typing import List, Tuple

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Check for invalid inputs
    if T <= 0 or M <= 0 or not herbs:
        return 0

    # Initialize the DP table
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Fill the DP table
    for i in range(1, M + 1):
        time_cost, value = herbs[i - 1]
        for t in range(1, T + 1):
            if time_cost <= t:
                dp[i][t] = max(dp[i - 1][t], dp[i - 1][t - time_cost] + value)
            else:
                dp[i][t] = dp[i - 1][t]

    return dp[M][T]
```

