    if not volumes or n == 0:
        return V

    dp = [[0] * (V + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for v in range(1, V + 1):
            if volumes[i - 1] <= v:
                dp[i][v] = max(dp[i - 1][v], dp[i - 1][v - volumes[i - 1]] + volumes[i - 1])
            else:
                dp[i][v] = dp[i - 1][v]

    return V - dp[n][V]
