MOD = 10**6 + 7

def calculate_arrangements(n, m, a) -> int:
    if m == 0:
        return 1
    if n == 0:
        return 0

    dp = [[0] * (m + 1) for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1

    for i in range(1, n):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= a[i]:
                dp[i][j] = (dp[i][j] + dp[i][j - a[i]]) % MOD

    result = 0
    for i in range(n):
        result = (result + dp[i][m]) % MOD

    return result
