def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    def dp(i, j):
        if i == n:
            return 1
        if j == 0:
            return 0
        if a[i] < j:
            return 0
        count = 0
        for k in range(j + 1):
            count = (count + dp(i + 1, j - k)) % MOD
        return count

    return dp(0, m)
