def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c: str, k: str) -> str:
        if not c.isalpha() or not k.isalpha():
            raise ValueError("Input characters must be alphabetic.")
        base = ord('A') if c.isupper() else ord('a')
        return chr((ord(c) - ord(k) - base) % 26 + base)

    key_length = len(key)
    plaintext = ''.join(shift_char(ciphertext[i], key[i % key_length]) for i in range(len(ciphertext)))
    return plaintext
```

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key = key.upper()
    ciphertext = ciphertext.upper()
    plaintext = []
    key_length = len(key)

    for i in range(len(ciphertext)):
        ciphertext_char = ciphertext[i]
        key_char = key[i % key_length]

        if ciphertext_char.isalpha() and key_char.isalpha():
            offset = (ord(ciphertext_char) - ord(key_char)) % 26
            plaintext_char = chr(ord('A') + offset)
            plaintext.append(plaintext_char)
        else:
            plaintext.append(ciphertext_char)

    return ''.join(plaintext).lower()

