def mod_inverse(a, b):
    if a == 0:
        return None
    t, newt = 0, 1
    r, newr = b, a

    while newr != 0:
        quotient = r // newr
        r, newr = newr, r - quotient * newr
        t, newt = newt, t - quotient * newt

    if r > 1:
        return None
    if t < 0:
        t += b

    return t
```

