            return -1  # Invalid budget value

        remaining_money = pocket_money_per_month - month_expenses
        if remaining_money >= 100:
            savings = remaining_money // 100 * 100
            total_savings += savings

    total_savings_with_interest = total_savings * 1.2
    return int(total_savings_with_interest)
