def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0

    # Calculate the maximum length of increasing subsequence ending at each position
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Calculate the maximum length of decreasing subsequence starting at each position
    lds = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The minimum number of students to leave is the total number of students
    # minus the maximum length of the choral formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, lis[i] + lds[i] - 1)

    return n - max_choir_length

