def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Initialize lists to store the length of the longest increasing subsequence
    # ending at each position and the length of the longest decreasing subsequence
    # starting at each position
    increase = [1] * n
    decrease = [1] * n

    # Compute the length of the longest increasing subsequence ending at each position
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                increase[i] = max(increase[i], increase[j] + 1)

    # Compute the length of the longest decreasing subsequence starting at each position
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                decrease[i] = max(decrease[i], decrease[j] + 1)

    # The minimum number of students to leave is the length of the heights list minus
    # the maximum length of the increasing and decreasing subsequences that can be combined
    max_length = 0
    for i in range(n):
        max_length = max(max_length, increase[i] + decrease[i] - 1)

    return n - max_length
