def min_groups(w, n, prices):
    if n % 2 != 0:
        raise ValueError("The number of souvenirs must be even.")
    if not all(0 <= price <= w for price in prices):
        raise ValueError("All prices must be non-negative and less than or equal to the weight limit.")

    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups
